<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import Icon from './Icon.vue';
import AdminWorkspace from './AdminWorkspace.vue';
import BusinessWorkspace from './BusinessWorkspace.vue';
import SalesWorkspace from './SalesWorkspace.vue';
import DeliveryWorkspace from './DeliveryWorkspace.vue';
import RecoveryPanel from './RecoveryPanel.vue';
import CommerceWorkspace from './CommerceWorkspace.vue';
import TradeWorkspace from './TradeWorkspace.vue';
import P3Workspace from './P3Workspace.vue';
import P4Workspace from './P4Workspace.vue';
import P4CompletionWorkspace from './P4CompletionWorkspace.vue';
type Tenant = { id:string; name:string; memberId:string; roles:string[]; status:string; subscriptionEnd:string };
type Session = { user:{displayName:string;username:string;platformOperator:boolean;mustChangePassword:boolean};csrfToken:string;activeTenantId:string|null;tenants:Tenant[];supportTenant?:Tenant|null;supportGrantId?:string|null;customerAccess?:{read:boolean;write:boolean;creditWrite:boolean;descriptionWrite:boolean}|null;businessAccess?:{contactRead:boolean;contactWrite:boolean;leads:{read:boolean;write:boolean};opportunities:{read:boolean;write:boolean};tasks:{read:boolean;write:boolean};activityRead:boolean;activityWrite:boolean};deliveryAccess?:{reports:boolean;export:boolean;customerImport:boolean;attachmentRead:boolean;attachmentWrite:boolean};commerceAccess?:{productRead:boolean;productWrite:boolean;quotes:{read:boolean;write:boolean};pdfExport:boolean;approve:boolean};tradeAccess?:{contracts:{read:boolean;write:boolean};amend:boolean;receiptRead:boolean;receiptWrite:boolean;confirm:boolean;reverse:boolean;export:boolean};p3Access?:{tickets:{read:boolean;write:boolean};slaManage:boolean;knowledgeRead:boolean;knowledgeWrite:boolean;knowledgePublish:boolean;campaigns:{read:boolean;write:boolean};campaignLaunch:boolean;integrationRead:boolean;integrationManage:boolean;export:boolean};p4Access?:{configurationRead:boolean;configurationManage:boolean;portalAccountManage:boolean;aiUse:boolean;aiReview:boolean} };
type Customer = {id:string;name:string;industry:string;level:string;source:string;region:string;creditCode:string|null;ownerMemberId:string;ownerName:string;description:string|null;version:number;updatedAt:string;canWrite:boolean;creditReadable:boolean;creditWritable:boolean;descriptionReadable:boolean;descriptionWritable:boolean;canShare:boolean;canTransfer:boolean};
type Page = {items:Customer[];total:number;page:number;pageSize:number};
const session=ref<Session|null>(null), health=ref('连接中'), busy=ref(false), error=ref(''), success=ref('');
const accountQuery=new URLSearchParams(window.location.search).get('account');
const requestedAccount=accountQuery&&['owner','platform-operator'].includes(accountQuery)?accountQuery:'';
const username=ref(requestedAccount||'owner'),password=ref(''),search=ref(''),page=ref(1),list=ref<Page>({items:[],total:0,page:1,pageSize:20}),owners=ref<{id:string;name:string}[]>([]);
const editor=ref<Customer|null>(null),creating=ref(false),requestKey=ref('');
const contactFilter=ref(''),salesFilter=ref(''),deliveryFilter=ref('');
const noCommerce={productRead:false,productWrite:false,quotes:{read:false,write:false},pdfExport:false,approve:false};
const commerceFilter=ref(''),tradeFilter=ref(''),tradeQuote=ref('');
const noTrade={contracts:{read:false,write:false},amend:false,receiptRead:false,receiptWrite:false,confirm:false,reverse:false,export:false};
const noDelivery={reports:false,export:false,customerImport:false,attachmentRead:false,attachmentWrite:false};
const forgot=ref(false),recoveryEnabled=ref(false);const resetQuery=new URLSearchParams(window.location.search).get('reset');const resetToken=ref(resetQuery&&/^[A-Za-z0-9_-]{43}$/.test(resetQuery)?resetQuery:'');if(resetQuery){const clean=new URL(window.location.href);clean.searchParams.delete('reset');window.history.replaceState({},'',clean.pathname+clean.search+clean.hash);}
const sourceLead=ref<{id:string;customerId:string;title:string}|null>(null);
const displayName=computed(()=>session.value?.user.displayName==='产品体验管理员'?'示例企业账号':session.value?.user.displayName);
const noBusiness={contactRead:false,leads:{read:false,write:false},opportunities:{read:false,write:false},tasks:{read:false,write:false},activityRead:false,activityWrite:false};
const view=ref('customers'),oldPassword=ref(''),newPassword=ref(''),confirmPassword=ref('');
const sidebarOpen=ref(false),aiPaneOpen=ref(false),quickSearch=ref('');
const theme=ref<'dark'|'light'>(localStorage.getItem('crm-theme')==='light'?'light':'dark');
const viewTitles:Record<string,string>={dashboard:'CRM 工作台',customers:'客户中心',contacts:'联系人',leads:'线索中心',opportunities:'商机与看板',activities:'客户跟进',tasks:'跟进待办',products:'产品目录',quotes:'报价管理','quote-approvals':'报价审批',contracts:'合同管理',receipts:'回款管理',reconciliation:'收款对账',tickets:'服务工单',knowledge:'知识库',campaigns:'营销活动',integrations:'开放集成','ai-assistant':'AI 助手',reports:'数据报表',exchange:'导入导出',attachments:'附件管理',notifications:'站内提醒',members:'组织成员',departments:'部门管理',policies:'角色权限',configuration:'行业配置','portal-accounts':'门户账号',billing:'套餐订阅',support:'支持授权',audits:'管理记录','platform-tenants':'企业与订阅','platform-plans':'套餐管理','platform-commercialization':'商业化运营','platform-renewals':'续费审核','platform-accounts':'登录账号','platform-support':'支持访问','platform-audits':'操作记录','platform-operations':'平台运维',password:'修改密码'};
const currentTitle=computed(()=>viewTitles[view.value]??'工作区');
function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';}
watch(theme,value=>{document.documentElement.classList.toggle('crm-dark',value==='dark');localStorage.setItem('crm-theme',value);},{immediate:true});
function quickFind(){if(!quickSearch.value.trim()||!session.value?.customerAccess?.read)return;search.value=quickSearch.value.trim();quickSearch.value='';page.value=1;navigate('customers');}
const shareRows=ref<{memberId:string;name:string;canWrite:boolean;expiresAt:string}[]>([]),shareOptions=ref<{id:string;name:string}[]>([]),shareMember=ref(''),shareWrite=ref(false),shareDays=ref(7),transferOwner=ref('');
const platformMode=computed(()=>view.value.startsWith('platform-'));
const admin=computed(()=>!!tenant.value?.roles.includes('TENANT_ADMIN')&&!session.value?.supportGrantId);
const tenantReadonly=computed(()=>!tenant.value||tenant.value.status!=='ACTIVE'||new Date(tenant.value.subscriptionEnd)<=new Date());
const tenantNav=[{id:'members',name:'组织成员'},{id:'departments',name:'部门管理'},{id:'policies',name:'角色权限'},{id:'configuration',name:'行业配置'},{id:'portal-accounts',name:'门户账号'},{id:'billing',name:'套餐订阅'},{id:'support',name:'支持授权'},{id:'audits',name:'管理记录'}];
const platformNav=[{id:'platform-tenants',name:'企业与订阅'},{id:'platform-plans',name:'套餐管理'},{id:'platform-commercialization',name:'商业化运营'},{id:'platform-renewals',name:'续费审核'},{id:'platform-accounts',name:'登录账号'},{id:'platform-support',name:'支持访问'},{id:'platform-audits',name:'操作记录'},{id:'platform-operations',name:'平台运维'}];
const entryHints:Record<string,string>={members:'新增、停用成员和分配角色',departments:'维护部门层级与成员归属',policies:'配置客户范围与字段权限',configuration:'配置行业模板、字段、标签、阶段与编号', 'portal-accounts':'开通外部客户账号并重置访问',billing:'查看额度、有效期及申请续费',support:'授予只读支持和查看访问记录',audits:'查看本企业的管理操作','platform-tenants':'开通企业，调整套餐与使用状态','platform-plans':'设置月费、成员、客户及功能额度','platform-commercialization':'查看 MRR、企业用量和人工订阅订单','platform-renewals':'核实凭据，确认或驳回续费','platform-accounts':'重置账号密码，撤销旧会话','platform-support':'进入企业明确授权的只读空间','platform-audits':'查看平台管理记录','platform-operations':'应用、数据库、附件、提醒与备份任务状态'};
const modal=ref<HTMLElement|null>(null);let previousFocus:HTMLElement|null=null,previousOverflow:string|null=null;
function restoreScroll(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
watch(creating,async open=>{if(open){previousFocus=document.activeElement as HTMLElement;if(previousOverflow===null)previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled)')?.focus({preventScroll:true});}else{restoreScroll();previousFocus?.focus({preventScroll:true});}});
function modalKeys(event:KeyboardEvent){if(!creating.value)return;if(event.key==='Escape'&&!busy.value){creating.value=false;return;}if(event.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
onMounted(()=>document.addEventListener('keydown',modalKeys));onUnmounted(()=>{document.removeEventListener('keydown',modalKeys);restoreScroll();});
const form=reactive({name:'',industry:'制造业',level:'B',source:'官网咨询',region:'',creditCode:'',ownerMemberId:'',description:''});
const tenant=computed(()=>session.value?.supportTenant??session.value?.tenants.find(t=>t.id===session.value?.activeTenantId));
const canCreate=computed(()=>tenant.value?.status==='ACTIVE' && new Date(tenant.value.subscriptionEnd)>new Date() && !!session.value?.customerAccess?.write&&!session.value?.supportGrantId);
const roles:Record<string,string>={TENANT_ADMIN:'企业管理',SALES_MANAGER:'销售经理',SALES:'销售',VIEWER:'只读成员'};
async function api<T>(path:string,method='GET',body?:unknown,headers:Record<string,string>={}):Promise<T>{
 const response=await fetch('/api/v1'+path,{method,credentials:'same-origin',headers:{...(body===undefined||body instanceof FormData?{}:{'Content-Type':'application/json'}),...(session.value?{'X-CSRF-Token':session.value.csrfToken,...(session.value.activeTenantId?{'X-Workspace-ID':session.value.activeTenantId}:{})}:{}),...headers},...(body===undefined?{}:{body:body instanceof FormData?body:JSON.stringify(body)})});
 const value=response.status===204?null:await response.json().catch(()=>({message:'服务暂未就绪，请稍后重试'}));
 if(!response.ok){if(response.status===401)session.value=null;if(value?.code==='TENANT_CONTEXT_CHANGED'){list.value={items:[],total:0,page:1,pageSize:20};creating.value=false;editor.value=null;const current=await fetch('/api/v1/auth/session',{credentials:'same-origin'});if(current.ok)session.value=await current.json();}const failure=new Error((value?.message||'操作未完成')+(value?.traceId?' · 编号 '+value.traceId.slice(0,8):'')) as Error&{status:number;code:string};failure.status=response.status;failure.code=value?.code??'';throw failure;}
 return value as T;
}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function load(){
 if(!tenant.value||!session.value?.customerAccess?.read){list.value={items:[],total:0,page:1,pageSize:20};return;}
 const workspaceId=session.value?.activeTenantId;const [data,options]=await Promise.all([api<Page>(`/customers?page=${page.value}&pageSize=20&q=${encodeURIComponent(search.value)}`),api<{id:string;name:string}[]>('/customers/owners')]);
 if(session.value?.activeTenantId===workspaceId){list.value=data;owners.value=options;}
}
function login(){return run(async()=>{session.value=await api<Session>('/auth/login','POST',{username:username.value,password:password.value});password.value='';list.value={items:[],total:0,page:1,pageSize:20};view.value=session.value.user.platformOperator?'platform-tenants':'customers';if(!session.value.user.mustChangePassword&&!session.value.user.platformOperator&&session.value.tenants.length===1)await select(session.value.tenants[0].id);});}
async function select(id:string){session.value=await api<Session>('/auth/active-tenant','POST',{tenantId:id});page.value=1;search.value='';editor.value=null;creating.value=false;list.value={items:[],total:0,page:1,pageSize:20};owners.value=[];contactFilter.value='';salesFilter.value='';deliveryFilter.value='';commerceFilter.value='';tradeFilter.value='';tradeQuote.value='';sourceLead.value=null;view.value=home();await load();}
function changeTenant(event:Event){const id=(event.target as HTMLSelectElement).value;if(id)return run(()=>select(id));}
function logout(){return run(async()=>{await api('/auth/logout','POST');session.value=null;list.value={items:[],total:0,page:1,pageSize:20};creating.value=false;editor.value=null;});}
function open(record?:Customer){editor.value=record??null;creating.value=true;error.value='';success.value='';requestKey.value=crypto.randomUUID();Object.assign(form,record?{name:record.name,industry:record.industry,level:record.level,source:record.source,region:record.region,creditCode:record.creditCode??'',ownerMemberId:record.ownerMemberId,description:record.description??''}:{name:'',industry:'制造业',level:'B',source:'官网咨询',region:'',creditCode:'',ownerMemberId:owners.value[0]?.id??'',description:''});shareRows.value=[];shareOptions.value=[];shareMember.value='';shareWrite.value=false;shareDays.value=7;transferOwner.value=record?.ownerMemberId??'';if(record?.canShare)run(async()=>{[shareRows.value,shareOptions.value]=await Promise.all([api<typeof shareRows.value>('/customers/'+record.id+'/shares'),api<typeof shareOptions.value>('/customers/'+record.id+'/share-recipients')]);});}
function save(){return run(async()=>{
 if(editor.value){await api<Customer>('/customers/'+editor.value.id,'PATCH',{expectedVersion:editor.value.version,name:form.name,industry:form.industry,level:form.level,source:form.source,region:form.region,...(editor.value.descriptionWritable?{description:form.description}:{}),...(editor.value.creditWritable?{creditCode:form.creditCode}:{})});}
 else{await api<Customer>('/customers','POST',{name:form.name,industry:form.industry,level:form.level,source:form.source,region:form.region,ownerMemberId:form.ownerMemberId,...(session.value?.customerAccess?.creditWrite?{creditCode:form.creditCode}:{}),...(session.value?.customerAccess?.descriptionWrite?{description:form.description}:{})},{'Idempotency-Key':requestKey.value});}
 creating.value=false;editor.value=null;page.value=1;await load();success.value='客户已保存到数据库';
});}
async function refreshSession(){session.value=await api<Session>('/auth/session');if(!platformMode.value&&view.value!=='password'&&((view.value==='contacts'&&!session.value?.businessAccess?.contactRead)||(view.value==='leads'&&!session.value?.businessAccess?.leads.read)||(view.value==='opportunities'&&!session.value?.businessAccess?.opportunities.read)||(view.value==='tasks'&&!session.value?.businessAccess?.tasks.read)||(view.value==='activities'&&!session.value?.businessAccess?.activityRead)||(view.value==='reports'&&!session.value?.deliveryAccess?.reports)||(view.value==='exchange'&&!session.value?.deliveryAccess?.export&&!session.value?.deliveryAccess?.customerImport)||(view.value==='attachments'&&!session.value?.deliveryAccess?.attachmentRead)||(view.value==='products'&&!session.value?.commerceAccess?.productRead)||(view.value==='quotes'&&(!session.value?.commerceAccess?.quotes.read||!session.value?.customerAccess?.read))||(view.value==='quote-approvals'&&(!session.value?.commerceAccess?.approve||!session.value?.customerAccess?.read))||(view.value==='contracts'&&(!session.value?.tradeAccess?.contracts.read||!session.value?.customerAccess?.read))||(['receipts','reconciliation'].includes(view.value)&&(!session.value?.tradeAccess?.receiptRead||!session.value?.customerAccess?.read))||(view.value==='notifications'&&!session.value?.businessAccess?.tasks.read)||(view.value==='ai-assistant'&&!session.value?.p4Access?.aiUse)||(!['dashboard','customers','contacts','leads','opportunities','activities','tasks','reports','exchange','attachments','notifications','products','quotes','quote-approvals','contracts','receipts','reconciliation','ai-assistant'].includes(view.value)&&!admin.value)))view.value=home();}
function home(){return session.value?.supportGrantId?'customers':'dashboard';}
function openSales(section:string,customerId=''){salesFilter.value=customerId;sourceLead.value=null;view.value=section;}
function leadOpportunity(value:{id:string;customerId:string;title:string}){sourceLead.value=value;salesFilter.value='';view.value='opportunities';}
function openCustomerContacts(id:string){contactFilter.value=id;view.value='contacts';}
async function showCustomer(id:string){let record:Customer|undefined;await run(async()=>{record=await api<Customer>('/customers/'+id);view.value='customers';await load();});if(record)open(record);}
function openTrade(id='',quote=''){tradeFilter.value=id;tradeQuote.value=quote;view.value='contracts';}
function navigate(target:string){sidebarOpen.value=false;tradeFilter.value='';tradeQuote.value='';commerceFilter.value='';deliveryFilter.value='';salesFilter.value='';sourceLead.value=null;if(target==='contacts')contactFilter.value='';view.value=target;error.value='';success.value='';if(target==='customers')run(async()=>{await refreshSession();await load();});}
function supportEntered(value:Session){session.value=value;view.value='customers';page.value=1;search.value='';run(load);}
function exitSupport(){return run(async()=>{session.value=await api<Session>('/platform/support/exit','POST');view.value='platform-support';list.value={items:[],total:0,page:1,pageSize:20};});}
function changePassword(){return run(async()=>{if(newPassword.value!==confirmPassword.value)throw new Error('两次输入的新密码不一致');await api('/auth/password','POST',{oldPassword:oldPassword.value,newPassword:newPassword.value});username.value=session.value?.user.username??username.value;session.value=null;oldPassword.value='';newPassword.value='';confirmPassword.value='';success.value='密码已修改，请使用新密码重新登录';});}
function addShare(){return run(async()=>{if(!editor.value||!shareMember.value)throw new Error('请选择共享成员');await api('/customers/'+editor.value.id+'/shares','POST',{memberId:shareMember.value,canWrite:shareWrite.value,expiresAt:new Date(Date.now()+shareDays.value*86400000).toISOString()});shareRows.value=await api<typeof shareRows.value>('/customers/'+editor.value.id+'/shares');success.value='客户共享已保存';});}
function revokeShare(memberId:string){return run(async()=>{if(!editor.value)return;await api('/customers/'+editor.value.id+'/shares/'+memberId,'DELETE');shareRows.value=await api<typeof shareRows.value>('/customers/'+editor.value.id+'/shares');success.value='客户共享已撤销';});}
function transferCustomer(){return run(async()=>{if(!editor.value||!transferOwner.value)return;const value=await api<Customer>('/customers/'+editor.value.id+'/transfer','POST',{ownerMemberId:transferOwner.value,expectedVersion:editor.value.version});editor.value=value;form.ownerMemberId=value.ownerMemberId;await load();success.value='客户已转交';});}
async function download(path:string,name:string){const r=await fetch('/api/v1'+path,{credentials:'same-origin',headers:{...(session.value?.activeTenantId?{'X-Workspace-ID':session.value.activeTenantId}:{})}});if(!r.ok){if(r.status===401)session.value=null;const data=await r.json().catch(()=>({message:'下载未完成'}));const failure=new Error(data.message) as Error&{status:number};failure.status=r.status;throw failure;}const blob=await r.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openDelivery(section:string,id=''){deliveryFilter.value=id;view.value=section;}
function find(){page.value=1;return run(load);}
function turn(delta:number){page.value+=delta;return run(load);}
onMounted(async()=>{try{recoveryEnabled.value=(await api<{enabled:boolean}>('/auth/recovery/status')).enabled;}catch{}try{const h=await api<{status:string}>('/health');health.value=h.status==='UP'?'服务已连接':'服务异常';}catch{health.value='服务暂未连接';}try{session.value=await api<Session>('/auth/session');if(session.value.user.platformOperator&&!tenant.value)view.value='platform-tenants';else if(tenant.value)view.value=home();if(tenant.value&&!session.value.user.mustChangePassword)await load();}catch(e){if(session.value)error.value=e instanceof Error?e.message:'加载失败';}});
</script>

<template>
 <div class="live-shell" :class="{ 'workspace-active': !!session&&!resetToken&&!forgot, 'ai-open': aiPaneOpen&&!!session?.p4Access?.aiUse }">
  <header class="live-header">
   <a class="brand" href="?mode=live"><span class="brand-mark"><Icon name="layers" :size="23"/></span><span><strong>彬彬 CRM</strong><small>企业客户经营平台</small></span></a>
   <div v-if="session&&!resetToken&&!forgot" class="live-header-page">
    <button class="icon-button live-menu-toggle" aria-label="打开业务导航" :aria-expanded="sidebarOpen" @click="sidebarOpen=!sidebarOpen"><Icon name="menu"/></button>
    <div><small>{{session.user.platformOperator&&platformMode?'平台运营':'企业工作区'}} / {{currentTitle}}</small><strong>{{currentTitle}}</strong></div>
   </div>
   <div class="live-header-right">
    <form v-if="session&&!platformMode&&session.customerAccess?.read&&!session.user.mustChangePassword" class="live-quick-search" role="search" @submit.prevent="quickFind"><Icon name="search" :size="17"/><input v-model="quickSearch" aria-label="搜索客户名称" placeholder="搜索客户名称…" maxlength="100"/><kbd>Enter</kbd></form>
    <button v-if="session?.p4Access?.aiUse&&!session.user.mustChangePassword" class="live-ai-trigger" :aria-expanded="aiPaneOpen" @click="aiPaneOpen=!aiPaneOpen"><Icon name="spark" :size="17"/>AI 助手</button>
    <button class="icon-button live-theme-toggle" :aria-label="theme==='dark'?'切换浅色主题':'切换深色主题'" @click="toggleTheme"><Icon :name="theme==='dark'?'sun':'moon'" :size="18"/></button>
    <span class="live-connection"><i :class="{connected:health==='服务已连接'}"></i>{{health}}</span>
    <a v-if="!session" class="btn secondary" href="?mode=demo">浏览流程演示</a>
   </div>
  </header>
  <main class="live-main">
   <div v-if="error" class="live-alert error" role="alert">{{error}}</div><div v-if="success" class="live-alert ok" role="status">{{success}}</div>
   <RecoveryPanel v-if="resetToken||forgot" :request="api" :token="resetToken" :initial-username="username" @done="resetToken='';forgot=false"/><div v-else-if="!session" class="live-login-layout"><section class="live-intro"><span class="eyebrow">CLOUD TEST · v0.13</span><h1>从真实登录，<br/>开始客户经营。</h1><p>账号、企业权限与客户资料已经接入服务端。<br/>你保存的客户，可在重新登录后继续查看。</p><div class="live-intro-cards"><span><Icon name="lock"/>密码验证与会话</span><span><Icon name="building"/>独立企业空间</span><span><Icon name="users"/>客户数据持久化</span></div><div class="live-login-help"><strong>先选对操作身份</strong><p><b>客户企业端：</b>使用 owner 体验企业管理员，选择“星澜科技 · 测试企业”后进入 CRM 工作台。</p><p><b>你的平台后台：</b>使用 platform-operator 登录，开通客户企业、配置套餐、处理人工订阅订单。</p><div><button type="button" class="text-button" @click="username='owner'">填入企业管理账号</button><button type="button" class="text-button" @click="username='platform-operator'">填入平台运营账号</button></div><small>密码沿用已交付的测试密码；登录后仍由服务端检查权限。</small></div><div class="live-stage-note"><strong>当前开放：完整 P4</strong><p>已接入行业配置、客户门户、AI 助手与审计，以及套餐权益、企业用量和人工订阅订单。</p></div></section><form class="live-login-card" @submit.prevent="login"><span class="eyebrow">欢迎回来</span><h2>登录你的工作区</h2><p>本环境只使用虚构测试资料。</p><label for="live-username">账号<input id="live-username" v-model="username" autocomplete="username" required maxlength="128" :disabled="busy"/></label><label for="live-password">密码<input id="live-password" v-model="password" type="password" autocomplete="current-password" required maxlength="72" :disabled="busy"/></label><button class="btn primary full" :disabled="busy">{{busy?'正在登录…':'登录工作区'}}<Icon name="arrow" :size="17"/></button><button type="button" class="text-button" :disabled="busy||!recoveryEnabled" @click="forgot=true">忘记密码</button><small>{{recoveryEnabled?'使用核验邮箱找回，或联系管理员协助。':'邮箱找回尚未启用，可联系管理员协助。'}}</small><small>测试密码由项目负责人提供。暂未开放自助注册。</small></form></div>
   <template v-else-if="!resetToken&&!forgot">
    <div class="live-account-bar"><div><Icon name="shield" :size="18"/><strong>{{displayName}}</strong><span>{{session.user.username}}</span><span class="badge neutral">{{session.user.platformOperator?'你的平台运营端':'客户企业端'}}</span></div><button class="text-button" :disabled="busy" @click="navigate('password')">修改密码</button><button class="text-button" :disabled="busy" @click="logout">退出登录<Icon name="logout" :size="17"/></button></div>
    <div v-if="requestedAccount&&session.user.username!==requestedAccount" class="live-alert warning live-account-switch"><span>你当前使用 {{session.user.username}} 登录。进入{{requestedAccount==='platform-operator'?'平台运营':'企业管理'}}入口，请先退出并使用 {{requestedAccount}} 登录。</span><button class="btn secondary" :disabled="busy" @click="logout">退出并切换账号</button></div>
    <button v-if="sidebarOpen" class="live-nav-backdrop" aria-label="关闭业务导航" @click="sidebarOpen=false"></button>
    <nav v-if="!session.user.mustChangePassword" class="live-navigation" :class="{ open: sidebarOpen }" aria-label="工作区导航"><div class="live-nav-section">销售与客户</div><button v-if="tenant&&!session.supportGrantId" :class="{active:view==='dashboard'}" @click="navigate('dashboard')">CRM 工作台</button><button v-if="tenant&&session.customerAccess?.read" :class="{active:view==='customers'}" @click="navigate('customers')">客户中心</button><button v-if="tenant&&session.businessAccess?.contactRead" :class="{active:view==='contacts'}" @click="navigate('contacts')">联系人</button><button v-if="tenant&&session.businessAccess?.leads.read" :class="{active:view==='leads'}" @click="navigate('leads')">线索中心</button><button v-if="tenant&&session.businessAccess?.opportunities.read&&session.customerAccess?.read" :class="{active:view==='opportunities'}" @click="navigate('opportunities')">商机与看板</button><button v-if="tenant&&session.businessAccess?.activityRead" :class="{active:view==='activities'}" @click="navigate('activities')">客户跟进</button><button v-if="tenant&&session.businessAccess?.tasks.read" :class="{active:view==='tasks'}" @click="navigate('tasks')">跟进待办</button><div v-if="tenant&&!session.supportGrantId" class="live-nav-section">交易与交付</div><button v-if="tenant&&session.commerceAccess?.productRead" :class="{active:view==='products'}" @click="commerceFilter='';view='products'">产品目录</button><button v-if="tenant&&session.commerceAccess?.quotes.read&&session.customerAccess?.read" :class="{active:view==='quotes'}" @click="commerceFilter='';view='quotes'">报价</button><button v-if="tenant&&session.commerceAccess?.approve&&session.customerAccess?.read" :class="{active:view==='quote-approvals'}" @click="navigate('quote-approvals')">报价审批</button><button v-if="tenant&&session.tradeAccess?.contracts.read&&session.customerAccess?.read" :class="{active:view==='contracts'}" @click="navigate('contracts')">合同管理</button><button v-if="tenant&&session.tradeAccess?.receiptRead&&session.customerAccess?.read" :class="{active:view==='receipts'}" @click="navigate('receipts')">回款管理</button><button v-if="tenant&&session.tradeAccess?.receiptRead&&session.customerAccess?.read" :class="{active:view==='reconciliation'}" @click="navigate('reconciliation')">收款对账</button><div v-if="tenant&&!session.supportGrantId" class="live-nav-section">服务与增长</div><button v-if="tenant&&session.p3Access?.tickets.read" :class="{active:view==='tickets'}" @click="navigate('tickets')">服务工单</button><button v-if="tenant&&session.p3Access?.knowledgeRead" :class="{active:view==='knowledge'}" @click="navigate('knowledge')">知识库</button><button v-if="tenant&&session.p3Access?.campaigns.read" :class="{active:view==='campaigns'}" @click="navigate('campaigns')">营销活动</button><button v-if="tenant&&session.p3Access?.integrationRead" :class="{active:view==='integrations'}" @click="navigate('integrations')">开放集成</button><button v-if="tenant&&session.p4Access?.aiUse" :class="{active:view==='ai-assistant'}" @click="navigate('ai-assistant')">AI 助手</button><div v-if="tenant&&!session.supportGrantId" class="live-nav-section">数据与协作</div><button v-if="tenant&&session.deliveryAccess?.reports" :class="{active:view==='reports'}" @click="navigate('reports')">数据报表</button><button v-if="tenant&&(session.deliveryAccess?.export||session.deliveryAccess?.customerImport)" :class="{active:view==='exchange'}" @click="navigate('exchange')">导入导出</button><button v-if="tenant&&session.deliveryAccess?.attachmentRead" :class="{active:view==='attachments'}" @click="navigate('attachments')">附件</button><button v-if="tenant&&session.businessAccess?.tasks.read" :class="{active:view==='notifications'}" @click="navigate('notifications')">站内提醒</button><template v-if="admin"><div class="live-nav-section">企业管理</div><button v-for="item in tenantNav" :key="item.id" :class="{active:view===item.id}" @click="navigate(item.id)">{{item.name}}</button></template><button v-if="session.user.platformOperator&&!platformMode" @click="navigate('platform-tenants')">平台运营</button><template v-if="session.user.platformOperator&&platformMode"><div class="live-nav-section">平台运营</div><button v-for="item in platformNav" :key="item.id" :class="{active:view===item.id}" @click="navigate(item.id)">{{item.name}}</button></template></nav>
    <div v-if="session.user.mustChangePassword||view==='password'" class="live-password-card card"><h2>{{session.user.mustChangePassword?'首次登录，请修改初始密码':'修改登录密码'}}</h2><p>修改后，当前账号在所有企业的登录会话都会失效。</p><form @submit.prevent="changePassword"><label>当前密码<input v-model="oldPassword" type="password" required maxlength="72" autocomplete="current-password"/></label><label>新密码<input v-model="newPassword" type="password" required minlength="12" maxlength="72" autocomplete="new-password"/></label><label>再次输入新密码<input v-model="confirmPassword" type="password" required minlength="12" maxlength="72" autocomplete="new-password"/></label><button class="btn primary" :disabled="busy">保存新密码</button></form></div>
    <template v-else>
    <div v-if="session.supportGrantId" class="live-alert warning live-support-banner"><strong>运营支持 · 授权只读</strong><span>当前访问来自企业管理员的限时授权，成功读取会记录访问日志。</span><button class="btn secondary" :disabled="busy" @click="exitSupport">退出支持访问</button></div>
    <div v-if="!platformMode" class="live-tenant-bar"><label for="live-tenant">当前企业</label><select id="live-tenant" :value="session.activeTenantId??''" @change="changeTenant" :disabled="busy||!!session.supportGrantId"><option v-if="session.supportTenant" :value="session.supportTenant.id">{{session.supportTenant.name}} · 授权支持</option><option value="" disabled>选择已加入的企业</option><option v-for="t in session.tenants" :key="t.id" :value="t.id">{{t.name}}</option></select><div v-if="tenant" class="live-roles"><span v-for="r in tenant.roles" :key="r" class="badge neutral">{{roles[r]??r}}</span></div></div>
    <section v-if="admin&&view==='members'||platformMode&&view==='platform-tenants'" class="live-entry-guide" aria-labelledby="live-entry-title"><div class="live-entry-heading"><h2 id="live-entry-title">{{platformMode?'平台管理入口':'企业管理入口'}}</h2><p>{{platformMode?'在这里开通企业、配置套餐和处理续费。':'已选择企业，点击下方功能卡片开始管理。'}}</p></div><div class="live-entry-grid"><button v-for="item in platformMode?platformNav:tenantNav" :key="item.id" type="button" class="live-entry-card" @click="navigate(item.id)"><strong>{{item.name}}<Icon name="arrow" :size="16"/></strong><span>{{entryHints[item.id]}}</span></button></div><p v-if="!platformMode" class="live-entry-note">客户共享与转交：在客户列表点击“查看 / 编辑”，到弹窗下方操作。企业开通和套餐配置由平台运营账号处理。</p></section>
    <P3Workspace v-if="tenant&&['tickets','knowledge','campaigns','integrations'].includes(view)" :key="session.activeTenantId+view" :section="view" :request="api" :readonly="tenantReadonly" :access="session.p3Access"/><P4Workspace v-else-if="tenant&&['configuration','portal-accounts'].includes(view)" :key="session.activeTenantId+view" :section="view" :request="api" :readonly="tenantReadonly" :manage="view==='configuration'?!!session.p4Access?.configurationManage:!!session.p4Access?.portalAccountManage"/><P4CompletionWorkspace v-else-if="view==='platform-commercialization'||tenant&&view==='ai-assistant'" :key="(session.activeTenantId??'platform')+view" :section="view" :request="api" :readonly="tenantReadonly" :ai-review="!!session.p4Access?.aiReview"/><TradeWorkspace v-else-if="tenant&&['contracts','receipts','reconciliation'].includes(view)" :key="session.activeTenantId+view+tradeFilter+tradeQuote" :section="view" :request="api" :download="download" :access="session.tradeAccess??noTrade" :readonly="tenantReadonly" :customer-id="tradeFilter" :quote-id="tradeQuote" :attachment-read="!!session.deliveryAccess?.attachmentRead" :attachment-write="!!session.deliveryAccess?.attachmentWrite" :customer-write="!!session.customerAccess?.write" @clear-filter="tradeFilter=''" @customer="showCustomer" @navigate="navigate"/><CommerceWorkspace v-else-if="tenant&&['products','quotes','quote-approvals'].includes(view)" :key="session.activeTenantId+view+commerceFilter" :section="view" :request="api" :download="download" :contract-write="!!session.tradeAccess?.contracts.write" @contract="id=>openTrade('',id)" :access="session.commerceAccess??noCommerce" :readonly="tenantReadonly" :customer-write="!!session.customerAccess?.write" :opportunity-read="!!session.businessAccess?.opportunities.read" :customer-id="commerceFilter" @customer="showCustomer" @clear-filter="commerceFilter=''"/><DeliveryWorkspace v-else-if="view==='platform-operations'||tenant&&['reports','exchange','attachments','notifications'].includes(view)" :key="(session.activeTenantId??'platform')+view+deliveryFilter" :section="view" :request="api" :download="download" :access="session.deliveryAccess??noDelivery" :business="session.businessAccess??noBusiness" :customer-read="!!session.customerAccess?.read" :readonly="tenantReadonly" :member-id="tenant?.memberId" :customer-id="deliveryFilter" @clear-filter="deliveryFilter=''" @customer="showCustomer" @navigate="navigate"/><SalesWorkspace v-else-if="tenant&&['dashboard','opportunities','tasks','activities'].includes(view)" :key="session.activeTenantId+view+salesFilter+(sourceLead?.id??'')" :section="view" :request="api" :readonly="tenantReadonly" :member-id="tenant.memberId" :access="session.businessAccess??noBusiness" :customer-read="!!session.customerAccess?.read" :customer-write="!!session.customerAccess?.write" :admin="admin" :delivery="session.deliveryAccess??noDelivery" :customer-id="salesFilter" :source-lead="sourceLead" @customer="showCustomer" @navigate="navigate" @clear-filter="salesFilter=''"/><BusinessWorkspace v-else-if="tenant&&(view==='contacts'||view==='leads')" :key="session.activeTenantId+view+contactFilter" :section="view" :request="api" :readonly="tenantReadonly" :write="view==='contacts'?!!session.businessAccess?.contactWrite:!!session.businessAccess?.leads.write" :member-id="tenant.memberId" :customer-id="view==='contacts'?contactFilter:''" @customer="showCustomer" @contacts="openCustomerContacts" :opportunity-write="!!session.businessAccess?.opportunities.write&&!!session.customerAccess?.write" @opportunity="leadOpportunity" @clear-filter="contactFilter=''"/><AdminWorkspace v-else-if="platformMode||(tenant&&view!=='customers')" :key="(session.activeTenantId??'platform')+view" :section="view" :request="api" :readonly="tenantReadonly" :member-id="tenant?.memberId" @refresh="refreshSession" @support="supportEntered"/><div v-else-if="!tenant" class="live-empty card"><Icon name="building" :size="36"/><h2>{{session.tenants.length?'先选择企业，再打开管理功能':'当前账号尚未加入企业'}}</h2><p>选择企业后，直接进入 CRM 工作台，左侧显示业务与企业管理菜单。体验客户企业 CRM 可先选择“星澜科技 · 测试企业”。平台运营账号负责开通企业、配置套餐、订阅订单和续费。</p><button v-for="t in session.tenants" :key="t.id" class="btn secondary" :disabled="busy" @click="run(()=>select(t.id))">{{t.name}}<Icon name="arrow" :size="16"/></button></div>
    <template v-else><div v-if="!session.customerAccess?.read" class="live-alert warning">当前角色没有客户读取权限。企业管理员可以在组织与权限页面继续管理。</div><div v-if="new Date(tenant.subscriptionEnd)<=new Date()" class="live-alert warning">订阅已到期，当前企业仅允许受控查看，不能新增或修改业务资料。</div><div class="page-heading"><div><span class="eyebrow">YOUR CUSTOMER WORKSPACE</span><h1>客户中心</h1><p>当前列表由服务端按企业和成员权限返回。</p></div><button v-if="canCreate" class="btn primary" :disabled="busy" @click="open()"><Icon name="plus" :size="17"/>新增客户</button></div>
     <section class="card live-customer-card"><form class="live-toolbar" @submit.prevent="find"><div class="live-search"><Icon name="search" :size="18"/><input v-model="search" placeholder="搜索客户名称…" aria-label="搜索客户名称" maxlength="100"/><button class="btn secondary" :disabled="busy">搜索</button></div><span>共 {{list.total}} 家可见客户</span><button type="button" class="icon-button" aria-label="刷新客户" :disabled="busy" @click="run(load)"><Icon name="refresh"/></button></form><div class="table-scroll"><table><thead><tr><th>客户名称</th><th>行业</th><th>等级</th><th>负责人</th><th>地区</th><th>操作</th></tr></thead><tbody><tr v-for="c in list.items" :key="c.id"><td><strong>{{c.name}}</strong><small class="live-customer-source">{{c.source}}</small></td><td>{{c.industry}}</td><td><span class="badge" :class="c.level==='A'?'green':'neutral'">{{c.level}}</span></td><td>{{c.ownerName}}</td><td>{{c.region||'—'}}</td><td><button class="text-button" :disabled="busy" @click="open(c)">{{c.canWrite?'查看 / 编辑':'查看资料'}}</button><button v-if="session.businessAccess?.contactRead" class="text-button live-contact-link" :disabled="busy" @click="openCustomerContacts(c.id)">联系人</button><button v-if="session.businessAccess?.opportunities.read" class="text-button" :disabled="busy" @click="openSales('opportunities',c.id)">商机</button><button v-if="session.businessAccess?.activityRead" class="text-button" :disabled="busy" @click="openSales('activities',c.id)">跟进</button><button v-if="session.businessAccess?.tasks.read" class="text-button" :disabled="busy" @click="openSales('tasks',c.id)">待办</button><button v-if="session.tradeAccess?.contracts.read" class="text-button" @click="openTrade(c.id)">合同</button><button v-if="session.commerceAccess?.quotes.read" class="text-button" :disabled="busy" @click="commerceFilter=c.id;view='quotes'">报价</button><button v-if="tenant&&session.commerceAccess?.approve&&session.customerAccess?.read" :class="{active:view==='quote-approvals'}" @click="navigate('quote-approvals')">报价审批</button><button v-if="session.deliveryAccess?.attachmentRead" class="text-button" :disabled="busy" @click="openDelivery('attachments',c.id)">附件</button></td></tr><tr v-if="!list.items.length"><td colspan="6" class="empty-cell">{{busy?'正在加载客户…':'当前没有可见的客户资料'}}</td></tr></tbody></table></div><div class="live-pagination"><span>第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=list.total" @click="turn(1)">下一页</button></div></section>
     <div class="live-stage-note"><strong>本次开发范围</strong><p>客户、联系人、线索转换、商机与阶段历史、跟进和待办均已开放。数据报表、导入导出、附件和站内提醒可从左侧导航进入；组织成员、部门管理、角色权限和套餐订阅供企业管理员使用。平台账号负责企业开通、套餐管理、续费和平台运维。</p></div>
    </template>
    </template>
   </template>
  </main>
  <aside v-if="session?.p4Access?.aiUse&&aiPaneOpen&&!session.user.mustChangePassword&&!resetToken&&!forgot" class="live-ai-pane" aria-label="AI 辅助面板">
   <div class="live-ai-pane-head"><span class="live-ai-orb"><Icon name="spark" :size="19"/></span><div><small>CONTEXTUAL INTELLIGENCE</small><strong>AI 业务助手</strong></div><button class="icon-button" aria-label="关闭 AI 面板" @click="aiPaneOpen=false"><Icon name="close" :size="18"/></button></div>
   <div class="live-ai-pane-body"><div class="live-ai-context"><span class="eyebrow">当前工作上下文</span><strong>{{currentTitle}}</strong><p>AI 任务仅使用你有权访问的业务记录，并按服务端白名单发送字段。</p></div>
    <div class="live-ai-tasks"><span class="eyebrow">可用能力</span><div><Icon name="users" :size="16"/><span>客户经营摘要</span></div><div><Icon name="target" :size="16"/><span>商机推进建议</span></div><div><Icon name="note" :size="16"/><span>工单回复草稿</span></div></div>
    <p class="live-ai-disclaimer">生成前需选择具体记录并确认数据发送；结果供人工审核，不会自动修改 CRM 数据。供应商未配置时，入口会明确显示不可用。</p>
    <button class="btn primary full" @click="navigate('ai-assistant');aiPaneOpen=false">进入 AI 工作区<Icon name="arrow" :size="16"/></button>
   </div>
  </aside>
  <Teleport to="body"><div v-if="creating" class="modal-backdrop" @click.self="!busy&&(creating=false)"><section ref="modal" class="live-editor" role="dialog" aria-modal="true" aria-labelledby="live-editor-title"><div class="live-editor-heading"><h2 id="live-editor-title">{{editor?'客户资料':'新增客户'}}</h2><button class="icon-button" aria-label="关闭客户资料" :disabled="busy" @click="creating=false"><Icon name="close"/></button></div><form @submit.prevent="save"><div class="live-editor-body"><fieldset :disabled="busy||!!editor&&!editor.canWrite"><div class="live-form-grid"><label class="wide">客户名称<input v-model="form.name" required maxlength="200"/></label><label>行业<input v-model="form.industry" required maxlength="80"/></label><label>客户等级<select v-model="form.level"><option>A</option><option>B</option><option>C</option></select></label><label>客户来源<input v-model="form.source" required maxlength="80"/></label><label>地区<input v-model="form.region" maxlength="100"/></label><label class="wide">负责人<select v-model="form.ownerMemberId" required :disabled="!!editor"><option v-if="editor" :value="editor.ownerMemberId">{{editor.ownerName}}</option><option v-for="o in owners" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label class="wide">统一社会信用代码（可选）<input v-model="form.creditCode" maxlength="18" :disabled="editor?!editor.creditWritable:!session?.customerAccess?.creditWrite" :placeholder="editor&&!editor.creditReadable?'当前角色不可见':'有效的 18 位编码'"/></label><label class="wide">客户备注<textarea v-model="form.description" :disabled="editor?!editor.descriptionWritable:!session?.customerAccess?.descriptionWrite" :placeholder="editor&&!editor.descriptionReadable?'当前角色不可见':''" rows="3" maxlength="4000"></textarea></label></div></fieldset><div v-if="editor?.canShare" class="live-customer-access"><h3>客户共享</h3><p>本人负责或管理范围内的客户可共享；获得写共享的成员不能自动再次转授。</p><div v-for="sh in shareRows" :key="sh.memberId" class="live-share-row"><span>{{sh.name}} · {{sh.canWrite?'可编辑':'只读'}} <small>{{new Date(sh.